public static class PortableProfile {
 static byte[] Magic=Encoding.ASCII.GetBytes("SFTV0001");
 static byte[] Random(int n){var b=new byte[n];using(var r=RandomNumberGenerator.Create())r.GetBytes(b);return b;}
 public static byte[] Seal(Settings s,string password){if(password.Length<10)throw new Exception("Bitte mindestens 10 Zeichen als Exportpasswort verwenden.");byte[] plain;using(var m=new MemoryStream()){new XmlSerializer(typeof(Settings)).Serialize(m,s);plain=m.ToArray();}var salt=Random(16);var iv=Random(16);using(var k=new Rfc2898DeriveBytes(password,salt,600000,HashAlgorithmName.SHA256)){var enc=k.GetBytes(32);var auth=k.GetBytes(32);byte[] cipher;using(var a=Aes.Create()){a.Key=enc;a.IV=iv;using(var t=a.CreateEncryptor())cipher=t.TransformFinalBlock(plain,0,plain.Length);}var body=Magic.Concat(salt).Concat(iv).Concat(cipher).ToArray();using(var h=new HMACSHA256(auth))return body.Concat(h.ComputeHash(body)).ToArray();}}
 public static Settings Open(byte[] b,string password){if(b.Length<88||b.Length>8388608||!b.Take(8).SequenceEqual(Magic))throw new Exception("Keine gültige SpielfeldTV-Exportdatei.");using(var k=new Rfc2898DeriveBytes(password,b.Skip(8).Take(16).ToArray(),600000,HashAlgorithmName.SHA256)){var enc=k.GetBytes(32);var auth=k.GetBytes(32);byte[] expected;using(var h=new HMACSHA256(auth))expected=h.ComputeHash(b,0,b.Length-32);int diff=0;for(int i=0;i<32;i++)diff|=expected[i]^b[b.Length-32+i];if(diff!=0)throw new Exception("Passwort falsch oder Exportdatei beschädigt.");byte[] plain;using(var a=Aes.Create()){a.Key=enc;a.IV=b.Skip(24).Take(16).ToArray();using(var t=a.CreateDecryptor())plain=t.TransformFinalBlock(b,40,b.Length-72);}using(var m=new MemoryStream(plain))using(var r=XmlReader.Create(m,new XmlReaderSettings{DtdProcessing=DtdProcessing.Prohibit,XmlResolver=null,MaxCharactersInDocument=8388608})){var s=(Settings)new XmlSerializer(typeof(Settings)).Deserialize(r);Validate(s);return s;}}}
 public static void Validate(Settings s){if(s.Cameras==null||s.Pages==null||s.ActivePages==null||s.DisabledScreens==null||s.ViewerCaptions==null||s.Cameras.Count>200||s.Pages.Count<1||s.Pages.Count>100)throw new Exception("Ungültige Konfiguration.");foreach(var c in s.Cameras){c.Validate();if(String.IsNullOrEmpty(c.Id))throw new Exception("Kamera-ID fehlt.");}if(s.Cameras.Select(c=>c.Id).Distinct().Count()!=s.Cameras.Count)throw new Exception("Doppelte Kamera-ID.");foreach(var p in s.Pages){if(p.Slots==null||p.Slots.Count>100||String.IsNullOrWhiteSpace(p.Name))throw new Exception("Ungültiger Tab.");p.Normalize();if(p.Slots.Any(id=>id!=""&&!s.Cameras.Any(c=>c.Id==id)))throw new Exception("Raster verweist auf fehlende Kamera.");}s.Cache=Math.Max(100,Math.Min(3000,s.Cache));}
}
public static class MonitorNames {
 [StructLayout(LayoutKind.Sequential,CharSet=CharSet.Unicode)] struct Device {public int cb;[MarshalAs(UnmanagedType.ByValTStr,SizeConst=32)]public string name;[MarshalAs(UnmanagedType.ByValTStr,SizeConst=128)]public string text;public int flags;[MarshalAs(UnmanagedType.ByValTStr,SizeConst=128)]public string id;[MarshalAs(UnmanagedType.ByValTStr,SizeConst=128)]public string key;}
 [DllImport("user32.dll",CharSet=CharSet.Unicode)] static extern bool EnumDisplayDevices(string name,uint index,ref Device device,uint flags);
 public static string Label(Screen s){var d=new Device();d.cb=Marshal.SizeOf(d);string name="Monitor";var entry=DisplayConfigNames.Read().FirstOrDefault(x=>x.Gdi==s.DeviceName);if(entry!=null&&!String.IsNullOrWhiteSpace(entry.Name))return s.DeviceName.Replace("\\\\.\\DISPLAY","Bildschirm ")+" · "+entry.Name+" · "+s.Bounds.Width+"×"+s.Bounds.Height+(s.Primary?" · Hauptanzeige":"");if(EnumDisplayDevices(s.DeviceName,0,ref d,0)&&!String.IsNullOrWhiteSpace(d.text))name=d.text;return s.DeviceName.Replace("\\\\.\\DISPLAY","Bildschirm ")+" · "+name+" · "+s.Bounds.Width+"×"+s.Bounds.Height+(s.Primary?" · Hauptanzeige":"");}
 public static void Identify(){foreach(var s in Screen.AllScreens){var f=new Form{FormBorderStyle=FormBorderStyle.None,StartPosition=FormStartPosition.Manual,Bounds=new Rectangle(s.Bounds.Left+30,s.Bounds.Top+30,Math.Min(700,s.Bounds.Width-60),120),TopMost=true,BackColor=UI.Card};f.Controls.Add(new Label{Text=Label(s),Dock=DockStyle.Fill,TextAlign=ContentAlignment.MiddleCenter,ForeColor=Color.White,Font=new Font("Segoe UI",19,FontStyle.Bold)});var timer=new Timer{Interval=3500};timer.Tick+=(a,b)=>{timer.Stop();f.Close();timer.Dispose();};f.Show();timer.Start();}}
}
