 public RemapDialog(Settings settings){s=settings;old=s.Pages.Select(p=>p.Screen).Distinct().ToList();Text="Bildschirme am Ziel-PC zuordnen";Size=new Size(800,440);UI.Style(this);var panel=new FlowLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(15),FlowDirection=FlowDirection.TopDown,AutoScroll=true,WrapContents=false};panel.Controls.Add(UI.Label("Jede bisherige Anzeige einem Bildschirm dieses PCs zuordnen.\nMehrere Ansichten können als Tabs denselben Bildschirm nutzen."));foreach(var id in old){panel.Controls.Add(UI.Label(String.Join(", ",s.Pages.Where(p=>p.Screen==id).Select(p=>p.Name))));var c=UI.Combo();c.Width=710;foreach(var screen in Screen.AllScreens)c.Items.Add(new Choice{Id=screen.DeviceName,Name=MonitorNames.Label(screen)});c.SelectedIndex=-1;combos.Add(c);panel.Controls.Add(c);}panel.Controls.Add(UI.Button("Bildschirme identifizieren",(a,b)=>MonitorNames.Identify()));panel.Controls.Add(UI.Button("Zuordnung übernehmen",(a,b)=>{if(combos.Any(c=>c.SelectedItem==null)){MessageBox.Show("Bitte alle Anzeigen zuordnen.");return;}var map=old.Select((id,i)=>new {id,target=((Choice)combos[i].SelectedItem).Id}).ToDictionary(x=>x.id,x=>x.target);var disabled=s.DisabledScreens.ToArray();if(s.Pages.GroupBy(p=>map[p.Screen]+"|"+p.Name).Any(g=>g.Count()>1)){MessageBox.Show("Gleichnamige Tabs bitte verschiedenen Bildschirmen zuordnen.");return;}foreach(var p in s.Pages){p.Screen=map[p.Screen];p.ScreenKey=DisplayConfigNames.Key(p.Screen);}s.DisabledScreens=disabled.Where(map.ContainsKey).Select(id=>map[id]).Distinct().ToList();s.ViewerCaptions=s.ViewerCaptions.Where(c=>map.ContainsKey(c.Screen)).Select(c=>new ViewerCaption{Screen=map[c.Screen],ScreenKey=DisplayConfigNames.Key(map[c.Screen]),Title=c.Title}).GroupBy(c=>c.Screen).Select(g=>g.First()).ToList();s.ActivePages=s.ActivePages.Select(v=>{int split=v.IndexOf("|");if(split<0)return "";string id=v.Substring(0,split);return map.ContainsKey(id)?map[id]+v.Substring(split):"";}).Where(v=>v!="").ToList();if(s.Pages.GroupBy(p=>p.Screen+"|"+p.Name).Any(g=>g.Count()>1)){MessageBox.Show("Gleichnamige Tabs bitte verschiedenen Bildschirmen zuordnen.");return;}DialogResult=DialogResult.OK;}));Controls.Add(panel);}
}
