public class UpdateCenter:Form {
 const string Repo="ROBOTEXPERT247/SpielfeldTV"; public const string Current="0.8.2";
 Label status=UI.Label("Installiert: "+Current);TextBox notes=new TextBox{Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical,Dock=DockStyle.Fill,BackColor=UI.Card,ForeColor=UI.Ink};Button install;Dictionary<string,object> asset;MainForm owner;
 public UpdateCenter(MainForm main){owner=main;Text="GitHub Update-Center · SpielfeldTV";Size=new Size(760,530);UI.Style(this);var top=UI.Bar();top.Controls.Add(status);top.Controls.Add(UI.Button("Nach Updates suchen",async(a,b)=>await Check()));install=UI.Button("Update laden und installieren",async(a,b)=>await Install());install.Enabled=false;var bottom=UI.Bar();bottom.Dock=DockStyle.Bottom;bottom.Controls.Add(install);bottom.Controls.Add(UI.Button("Releases auf GitHub",(a,b)=>System.Diagnostics.Process.Start("https://github.com/"+Repo+"/releases")));Controls.Add(notes);Controls.Add(top);Controls.Add(bottom);Shown+=async(a,b)=>await Check();}
 static WebClient Client(){ServicePointManager.SecurityProtocol|=SecurityProtocolType.Tls12;var w=new WebClient();w.Headers["User-Agent"]="SpielfeldTV/"+Current;w.Headers["Accept"]="application/vnd.github+json";return w;}
 public static bool TrustedAsset(string url){Uri u;return Uri.TryCreate(url,UriKind.Absolute,out u)&&u.Scheme=="https"&&u.Host=="github.com"&&u.AbsolutePath.StartsWith("/"+Repo+"/releases/download/",StringComparison.Ordinal)&&u.UserInfo=="";}
 async Task Check(){install.Enabled=false;asset=null;status.Text="Suche öffentliche Releases …";try{string json;using(var w=Client())json=await w.DownloadStringTaskAsync("https://api.github.com/repos/"+Repo+"/releases/latest");var release=new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(json);string tag=(string)release["tag_name"];Version next; if(!Version.TryParse(tag.TrimStart('v','V'),out next))throw new Exception("Release enthält keine gültige Versionsnummer.");notes.Text=Convert.ToString(release["body"]).Replace("\n",Environment.NewLine);if(next<=new Version(Current)){status.Text="SpielfeldTV ist aktuell · "+Current;return;}foreach(var obj in (System.Collections.IEnumerable)release["assets"]){var a=(Dictionary<string,object>)obj;string name=Convert.ToString(a["name"]);if(name=="SpielfeldTV-Update-"+tag.TrimStart('v','V')+".exe")asset=a;}if(asset==null)throw new Exception("Dieses Release enthält kein passendes Windows-Update.");object digest;string hash=asset.TryGetValue("digest",out digest)?Convert.ToString(digest):"";if(!System.Text.RegularExpressions.Regex.IsMatch(hash,@"^sha256:[a-fA-F0-9]{64}$")||!TrustedAsset(Convert.ToString(asset["browser_download_url"])))throw new Exception("Updatequelle oder SHA-256-Prüfsumme fehlt.");status.Text="Neue Version verfügbar: "+tag;install.Enabled=true;}catch(WebException ex){var response=ex.Response as HttpWebResponse;status.Text=response!=null&&response.StatusCode==HttpStatusCode.NotFound?"Noch kein Release veröffentlicht.":"GitHub nicht erreichbar. Später erneut versuchen.";}catch(Exception ex){status.Text=ex.Message;}}
 async Task Install(){if(asset==null)return;install.Enabled=false;string file=System.IO.Path.Combine(System.IO.Path.GetTempPath(),"SpielfeldTV-Update-"+Guid.NewGuid().ToString("N")+".exe");try{using(var w=Client()){w.DownloadProgressChanged+=(a,b)=>status.Text="Download: "+b.ProgressPercentage+" %";await w.DownloadFileTaskAsync(Convert.ToString(asset["browser_download_url"]),file);}string actual;using(var sha=SHA256.Create())using(var stream=File.OpenRead(file))actual=BitConverter.ToString(sha.ComputeHash(stream)).Replace("-","").ToLowerInvariant();string expected=Convert.ToString(asset["digest"]).Substring(7).ToLowerInvariant();if(actual!=expected)throw new Exception("Prüfsumme stimmt nicht. Update wird nicht gestartet.");status.Text="Download geprüft. Anwendung wird geschlossen …";System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo(file){UseShellExecute=true,Arguments="--wait-pid "+System.Diagnostics.Process.GetCurrentProcess().Id});DialogResult=DialogResult.OK;owner.Close();}catch(Exception ex){UI.Error(ex);install.Enabled=true;}}
}
}
namespace SpielfeldTV {
public static class DisplayConfigNames {
 [DllImport("user32.dll")] static extern int GetDisplayConfigBufferSizes(uint flags,out uint paths,out uint modes);
 [DllImport("user32.dll")] static extern int QueryDisplayConfig(uint flags,ref uint paths,IntPtr path,ref uint modes,IntPtr mode,IntPtr topology);
 [DllImport("user32.dll")] static extern int DisplayConfigGetDeviceInfo(IntPtr packet);
 public class Entry {public string Gdi,Name,Key;}
 static IntPtr Packet(int type,int size,IntPtr path,int offset){var p=Marshal.AllocHGlobal(size);Marshal.Copy(new byte[size],0,p,size);Marshal.WriteInt32(p,0,type);Marshal.WriteInt32(p,4,size);for(int i=0;i<12;i++)Marshal.WriteByte(p,8+i,Marshal.ReadByte(path,offset+i));return p;}
 public static List<Entry> Read(){var result=new List<Entry>();try{for(int attempt=0;attempt<3;attempt++){uint pc,mc;if(GetDisplayConfigBufferSizes(2,out pc,out mc)!=0)return result;IntPtr paths=Marshal.AllocHGlobal((int)pc*72),modes=Marshal.AllocHGlobal((int)mc*64);try{int rc=QueryDisplayConfig(2,ref pc,paths,ref mc,modes,IntPtr.Zero);if(rc==122)continue;if(rc!=0)return result;for(int i=0;i<pc;i++){IntPtr path=IntPtr.Add(paths,i*72);IntPtr source=Packet(1,84,path,0),target=Packet(2,420,path,20);try{if(DisplayConfigGetDeviceInfo(source)==0&&DisplayConfigGetDeviceInfo(target)==0)result.Add(new Entry{Gdi=Marshal.PtrToStringUni(IntPtr.Add(source,20)),Name=Marshal.PtrToStringUni(IntPtr.Add(target,36)),Key=Marshal.PtrToStringUni(IntPtr.Add(target,164))});}finally{Marshal.FreeHGlobal(source);Marshal.FreeHGlobal(target);}}return result;}finally{Marshal.FreeHGlobal(paths);Marshal.FreeHGlobal(modes);}}}catch{}return result;}
 public static void Resolve(Settings s){var map=Read();if(s.ViewerCaptions!=null)foreach(var caption in s.ViewerCaptions){var match=map.FirstOrDefault(x=>!String.IsNullOrEmpty(caption.ScreenKey)&&x.Key==caption.ScreenKey);if(match!=null)caption.Screen=match.Gdi;}foreach(var p in s.Pages){if(!String.IsNullOrEmpty(p.ScreenKey)){var found=map.FirstOrDefault(x=>x.Key==p.ScreenKey);if(found!=null){string old=p.Screen;p.Screen=found.Gdi;s.ActivePages=s.ActivePages.Select(v=>v.StartsWith(old+"|")?p.Screen+v.Substring(old.Length):v).ToList();if(s.DisabledScreens.Remove(old))s.DisabledScreens.Add(p.Screen);}else if(Screen.AllScreens.Any(x=>x.DeviceName==p.Screen)){string old=p.Screen;p.Screen="Nicht verbunden: "+old;if(s.DisabledScreens.Remove(old))s.DisabledScreens.Add(p.Screen);}}else{var found=map.FirstOrDefault(x=>x.Gdi==p.Screen);if(found!=null)p.ScreenKey=found.Key;}}}
 public static string Key(string gdi){var e=Read().FirstOrDefault(x=>x.Gdi==gdi);return e==null?"":e.Key;}
}
}


