namespace SpielfeldTV {
public sealed class CameraPackets {
 const int Limit=16*1024*1024;byte[] bytes=new byte[65536];int start,end;
 public void AddRange(byte[] data){int used=end-start;if(data.Length>Limit-used)throw new System.IO.IOException("Kamerapaket überschreitet das Empfangslimit.");if(bytes.Length-end<data.Length){if(used+data.Length<=bytes.Length){System.Buffer.BlockCopy(bytes,start,bytes,0,used);}else{int size=bytes.Length;while(size<used+data.Length)size=Math.Min(Limit,size*2);var next=new byte[size];System.Buffer.BlockCopy(bytes,start,next,0,used);bytes=next;}start=0;end=used;}System.Buffer.BlockCopy(data,0,bytes,end,data.Length);end+=data.Length;}
 public bool TryRead(out byte[] frame){frame=null;int available=end-start;if(available<8)return false;if(bytes[start]!=0||bytes[start+1]!=0||bytes[start+2]!=1)throw new System.IO.IOException("Ungültiger Kamera-Paketkopf.");int tag=bytes[start+3],header=(tag==252||tag==254)?16:8;if(available<header)return false;long payload=(tag==252||tag==254)?System.BitConverter.ToInt32(bytes,start+12):tag==253?System.BitConverter.ToInt32(bytes,start+4):(tag==250||tag==249)?System.BitConverter.ToUInt16(bytes,start+6):-1;long length=payload+header;if(payload<0||length>8388608)throw new System.IO.IOException("Ungültige Kamera-Paketlänge.");if(available<length)return false;frame=new byte[(int)length];System.Buffer.BlockCopy(bytes,start,frame,0,frame.Length);start+=frame.Length;if(start==end)start=end=0;return true;}
}
