namespace SpielfeldTV {
public static class PacketTests {
 static byte[] Frame(int tag,int length){int header=tag==252?16:8;var b=new byte[header+length];b[2]=1;b[3]=(byte)tag;if(tag==252)BitConverter.GetBytes(length).CopyTo(b,12);else if(tag==253)BitConverter.GetBytes(length).CopyTo(b,4);else BitConverter.GetBytes((ushort)length).CopyTo(b,6);for(int i=header;i<b.Length;i++)b[i]=(byte)(i%251);return b;}
 public static void Run(){var frames=new[]{Frame(252,180000),Frame(253,27001),Frame(250,300),Frame(249,21),Frame(253,98000)};var all=frames.SelectMany(b=>b).ToArray();foreach(int fragment in new[]{1,37,1024,65536,all.Length}){var reader=new CameraPackets();int count=0;for(int offset=0;offset<all.Length;offset+=fragment){var part=new byte[Math.Min(fragment,all.Length-offset)];System.Buffer.BlockCopy(all,offset,part,0,part.Length);reader.AddRange(part);byte[] actual;while(reader.TryRead(out actual)){if(count>=frames.Length||!actual.SequenceEqual(frames[count++]))throw new Exception("Fragmentierte Kamerapakete verändert");}}if(count!=frames.Length)throw new Exception("Kamerapakete fehlen");}var bad=new CameraPackets();var invalid=Frame(252,1);BitConverter.GetBytes(Int32.MaxValue).CopyTo(invalid,12);bad.AddRange(invalid);bool rejected=false;try{byte[] b;bad.TryRead(out b);}catch(System.IO.IOException){rejected=true;}if(!rejected)throw new Exception("Ungültige Paketgröße akzeptiert");Console.WriteLine("PASS: camera packet fragmentation, combined packets, audio/video boundaries and size limit.");}
}
}



namespace SpielfeldTV {
public class ViewerCaption {public string Screen="",ScreenKey="",Title="";}
public static class ViewerTitles {
 public static void Ensure(Settings s){if(s.ViewerCaptions==null)s.ViewerCaptions=new List<ViewerCaption>();var ids=s.Pages.Select(p=>p.Screen).Distinct().ToList();List<DisplayConfigNames.Entry> monitors=null;for(int i=0;i<ids.Count;i++){string id=ids[i];if(s.ViewerCaptions.Any(c=>c.Screen==id))continue;if(monitors==null)monitors=DisplayConfigNames.Read();var m=monitors.FirstOrDefault(x=>x.Gdi==id);s.ViewerCaptions.Add(new ViewerCaption{Screen=id,ScreenKey=m==null?"":m.Key,Title="Spielfeld "+(i+1)});}}
 public static string Get(Settings s,string screen){Ensure(s);var c=s.ViewerCaptions.FirstOrDefault(x=>x.Screen==screen);return c==null||String.IsNullOrWhiteSpace(c.Title)?"Spielfeld "+Math.Max(1,s.Pages.Select(p=>p.Screen).Distinct().ToList().IndexOf(screen)+1):c.Title.Trim();}
 public static void Set(Settings s,string screen,string title){Ensure(s);var c=s.ViewerCaptions.FirstOrDefault(x=>x.Screen==screen);if(c==null){c=new ViewerCaption{Screen=screen,ScreenKey=DisplayConfigNames.Key(screen)};s.ViewerCaptions.Add(c);}c.Title=title;}
}
}


namespace SpielfeldTV {
public sealed class BrandStandby : Control {
 public static readonly Color Green=Color.FromArgb(19,27,20);
 static readonly Lazy<Bitmap> artwork=new Lazy<Bitmap>(()=>{var stream=System.Reflection.Assembly.GetExecutingAssembly().GetManifestResourceStream("branding.logo");if(stream==null){string file=System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"Bunker73-logo.png");if(System.IO.File.Exists(file))stream=System.IO.File.OpenRead(file);}if(stream==null)return null;using(stream)using(var image=Image.FromStream(stream))return new Bitmap(image);});
 public static bool HasLogo {get{return artwork.Value!=null;}}
 public BrandStandby(){Dock=DockStyle.Fill;BackColor=Green;Margin=Padding.Empty;TabStop=false;Visible=false;SetStyle(ControlStyles.UserPaint|ControlStyles.AllPaintingInWmPaint|ControlStyles.OptimizedDoubleBuffer|ControlStyles.ResizeRedraw,true);}
 protected override void OnPaint(PaintEventArgs e){e.Graphics.Clear(Green);var logo=artwork.Value;if(logo==null||Width<1||Height<1)return;float scale=Math.Min(Width*.60f/logo.Width,Height*.60f/logo.Height);int w=(int)(logo.Width*scale),h=(int)(logo.Height*scale);e.Graphics.InterpolationMode=System.Drawing.Drawing2D.InterpolationMode.HighQualityBicubic;e.Graphics.PixelOffsetMode=System.Drawing.Drawing2D.PixelOffsetMode.HighQuality;float saturation=.18f,brightness=.92f,red=(1-saturation)*.2126f,green=(1-saturation)*.7152f,blue=(1-saturation)*.0722f;var matrix=new System.Drawing.Imaging.ColorMatrix(new[]{new[]{(red+saturation)*brightness,red*brightness,red*brightness,0f,0f},new[]{green*brightness,(green+saturation)*brightness,green*brightness,0f,0f},new[]{blue*brightness,blue*brightness,(blue+saturation)*brightness,0f,0f},new[]{0f,0f,0f,.33f,0f},new[]{0f,0f,0f,0f,1f}});using(var attributes=new System.Drawing.Imaging.ImageAttributes()){attributes.SetColorMatrix(matrix);e.Graphics.DrawImage(logo,new Rectangle((Width-w)/2,(Height-h)/2,w,h),0,0,logo.Width,logo.Height,GraphicsUnit.Pixel,attributes);}}
}
}



